package main

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"strconv"
	"strings"

	"github.com/anthnel/devdesk/internal/nexusbench"
)

// listedImage is one image tag a repository lists, as the REST API of Nexus
// reports it: the name, the tag and the manifest digest ("sha256:<hex>", empty
// when the instance lists none).
type listedImage = nexusbench.ListedImage

// readImagesAnonymously lists the images of a repository without sending any
// credential: a read of what anonymous access allows, nothing else.
func readImagesAnonymously(ctx context.Context, baseURL, repository string) ([]listedImage, error) {
	return nexusbench.ListImagesAnonymously(ctx, baseURL, repository)
}

// nexusPodSelector is the label of the Nexus pod (see 20-deployment.yaml.tmpl).
const nexusPodSelector = "app.kubernetes.io/name=nexus"

// status reads the cluster and the descriptor and reports; it changes nothing.
// A pod that is missing or a Nexus that does not answer is a finding, not a
// failure: the exit code is 1 only when the cluster cannot be read at all.
func (s *session) status() int {
	runner, err := s.d.newRunner(s.p.Context)
	if err != nil {
		return s.fail(err)
	}
	if _, err := s.d.preflight(s.ctx, runner, s.p, nexusbench.OpStatus); err != nil {
		return s.fail(err)
	}
	pod := readPod(s, runner)
	if err := s.ctx.Err(); err != nil {
		return s.fail(err)
	}
	base := s.restURL()
	rest := "ready"
	if err := s.d.newProber().Ready(s.ctx, base); err != nil {
		// The error is not shown: the text of a failed call is not trusted.
		rest = "not ready"
	}
	if err := s.ctx.Err(); err != nil {
		return s.fail(err)
	}
	upstream := s.describeUpstream(runner)
	if err := s.ctx.Err(); err != nil {
		return s.fail(err)
	}
	path := s.descriptorPath()
	desc, descErr := nexusbench.LoadDescriptor(path)
	dataset := s.describeDataset(desc, descErr, base, rest == "ready")
	if err := s.ctx.Err(); err != nil {
		return s.fail(err)
	}
	_, _ = fmt.Fprintf(s.stdout, "bench: namespace %s, context %s\n", s.p.Namespace, s.p.Context)
	_, _ = fmt.Fprintf(s.stdout, "pod: %s\n", pod)
	_, _ = fmt.Fprintf(s.stdout, "rest: %s (%s)\n", rest, base)
	_, _ = fmt.Fprintf(s.stdout, "upstream: %s\n", upstream)
	_, _ = fmt.Fprintf(s.stdout, "descriptor: %s\n", describeDescriptor(path, desc, descErr, s.p))
	_, _ = fmt.Fprintf(s.stdout, "dataset: %s\n", dataset)
	return exitOK
}

// describeUpstream says what the cluster holds of the bench upstream. An
// upstream the bench did not deploy is not its to read; a deployment that
// cannot be read is a finding, never an error text (it can carry output of
// kubectl).
func (s *session) describeUpstream(r nexusbench.Runner) string {
	if !s.p.UpstreamIsBench() {
		return "not managed by the bench (NEXUS_BENCH_UPSTREAM_URL points elsewhere)"
	}
	state, err := s.d.readUpstream(s.ctx, r, s.p)
	if err != nil {
		return "unknown (the deployment " + upstreamName + " could not be read)"
	}
	switch state {
	case nexusbench.UpstreamReady:
		return "ready"
	case nexusbench.UpstreamCut:
		return "cut (0 replicas)"
	case nexusbench.UpstreamStarting:
		return "starting (no pod is ready yet)"
	}
	return "missing (run mise run nexus-bench:up)"
}

// upstreamName is the Deployment of the bench upstream.
const upstreamName = "bench-upstream"

// The two repositories that hold the data set. The group is never read: a read
// through it can cache an image (F9).
const (
	hostedRepository = "docker-hosted"
	proxyRepository  = "docker-proxy"
)

// describeDataset compares the data set the descriptor lists with what
// docker-hosted and docker-proxy list now. The listings are anonymous and read
// only, so what status cannot read is "unknown", never a failure.
func (s *session) describeDataset(d nexusbench.Descriptor, descErr error, base string, restReady bool) string {
	switch {
	case descErr != nil:
		return "unknown (no readable descriptor to compare with)"
	case len(d.Dataset) == 0:
		return "unknown (the descriptor lists no data set: run mise run nexus-bench:seed)"
	case !restReady:
		return "unknown (Nexus does not answer)"
	case !s.p.Anonymous:
		return "unknown (anonymous access is off and status sends no credential)"
	}
	var diffs int
	for _, repo := range []string{hostedRepository, proxyRepository} {
		listed, err := s.d.readImages(s.ctx, base, repo)
		if err != nil {
			return "unknown (the listing of " + repo + " failed)"
		}
		n, ok := compareListing(expectedIn(d.Dataset, repo), listed)
		if !ok {
			return "unknown (the listing of " + repo + " gives no digest)"
		}
		diffs += n
	}
	if diffs == 0 {
		return fmt.Sprintf("matches (%d images)", len(d.Dataset))
	}
	noun := "images"
	if diffs == 1 {
		noun = "image"
	}
	return fmt.Sprintf("differs (%d %s)", diffs, noun)
}

// expectedIn returns the images of the data set that repo holds: the hosted
// ones in docker-hosted, the ones cached in the proxy in docker-proxy.
func expectedIn(images []nexusbench.DescriptorImage, repo string) []nexusbench.DescriptorImage {
	var out []nexusbench.DescriptorImage
	for _, img := range images {
		if (repo == hostedRepository && img.Location == string(nexusbench.LocationHosted)) ||
			(repo == proxyRepository && img.CachedInProxy) {
			out = append(out, img)
		}
	}
	return out
}

// compareListing counts the differences between what a repository should hold
// and what it lists: an image that is missing or has another digest, and an
// image the data set does not know. ok is false when the listing gives no
// digest for an image that is there, which makes the comparison impossible.
func compareListing(want []nexusbench.DescriptorImage, listed []listedImage) (diffs int, ok bool) {
	have := make(map[string]string, len(listed))
	for _, img := range listed {
		have[img.Name+":"+img.Tag] = img.Digest
	}
	for _, img := range want {
		key := img.Name + ":" + img.Tag
		digest, found := have[key]
		delete(have, key)
		switch {
		case !found:
			diffs++
		case digest == "":
			return 0, false
		case digest != img.Digest:
			diffs++
		}
	}
	return diffs + len(have), true
}

// podList is the part of `kubectl get pods -o json` the report reads.
type podList struct {
	Items []struct {
		Metadata struct {
			Name              string `json:"name"`
			DeletionTimestamp string `json:"deletionTimestamp"`
		} `json:"metadata"`
		Status struct {
			Phase             string `json:"phase"`
			ContainerStatuses []struct {
				Ready        bool `json:"ready"`
				RestartCount int  `json:"restartCount"`
			} `json:"containerStatuses"`
		} `json:"status"`
	} `json:"items"`
}

// readPod describes the Nexus pod in one line: its phase, name, readiness and restarts.
func readPod(s *session, r nexusbench.Runner) string {
	stdout, _, err := r.Run(s.ctx, nil, "get", "pods", "-n", s.p.Namespace, "-l", nexusPodSelector, "-o", "json", "--request-timeout=10s")
	if err != nil {
		return "unknown (kubectl get pods failed)"
	}
	var list podList
	if err := json.Unmarshal(stdout, &list); err != nil {
		return "unknown (kubectl get pods returned something unreadable)"
	}
	if len(list.Items) == 0 {
		return "not found"
	}
	item := list.Items[0]
	phase := strings.ToLower(item.Status.Phase)
	if item.Metadata.DeletionTimestamp != "" {
		phase = "terminating"
	}
	if phase == "" {
		phase = "unknown"
	}
	ready, restarts := 0, 0
	for _, c := range item.Status.ContainerStatuses {
		if c.Ready {
			ready++
		}
		restarts += c.RestartCount
	}
	line := fmt.Sprintf("%s (%s, %d/%d ready, %d restarts", phase, item.Metadata.Name, ready, len(item.Status.ContainerStatuses), restarts)
	if len(list.Items) > 1 {
		line += fmt.Sprintf(", %d more pods", len(list.Items)-1)
	}
	return line + ")"
}

// describeDescriptor compares the versioned descriptor, as read at path, with
// the parameters of this run and says where they differ.
func describeDescriptor(path string, d nexusbench.Descriptor, err error, p nexusbench.Params) string {
	switch {
	case errors.Is(err, nexusbench.ErrNoDescriptor):
		return "not found (" + path + ")"
	case err != nil:
		return "unreadable (" + err.Error() + ")"
	}
	diffs := descriptorDiffs(d, p)
	if len(diffs) == 0 {
		return "matches (" + path + ")"
	}
	return "differs from the current parameters (" + path + ")\n  " + strings.Join(diffs, "\n  ")
}

// descriptorDiffs lists the fields of the descriptor that the parameters of
// this run would write differently. The hosts and the versions are left out:
// they come from the cluster, not from the parameters. So is the dataset, which
// the parameters know nothing of.
func descriptorDiffs(d nexusbench.Descriptor, p nexusbench.Params) []string {
	want := nexusbench.BuildDescriptor(p, nexusbench.DeployResult{}, nexusbench.ProvisionResult{}, nexusbench.SeedResult{})
	fields := []struct{ name, got, want string }{
		{"context", d.KubeContext, want.KubeContext},
		{"namespace", d.Namespace, want.Namespace},
		{"image", d.Image, want.Image},
		{"http nodePort", strconv.Itoa(d.REST.NodePort), strconv.Itoa(want.REST.NodePort)},
		{"docker nodePort", dockerPort(d), dockerPort(want)},
		{"upstream URL", upstreamURL(d), upstreamURL(want)},
		{"upstream image", d.Upstream.Image, want.Upstream.Image},
		{"anonymous access", anonymous(d), anonymous(want)},
	}
	var diffs []string
	for _, f := range fields {
		if f.got != f.want {
			diffs = append(diffs, fmt.Sprintf("%s: descriptor %s, current %s", f.name, f.got, f.want))
		}
	}
	return diffs
}

func dockerPort(d nexusbench.Descriptor) string {
	if len(d.DockerConnectors) == 0 {
		return "none"
	}
	return strconv.Itoa(d.DockerConnectors[0].NodePort)
}

func upstreamURL(d nexusbench.Descriptor) string {
	for _, r := range d.Repositories {
		if r.Type == "proxy" {
			return r.RemoteURL
		}
	}
	return "none"
}

func anonymous(d nexusbench.Descriptor) string {
	for _, a := range d.Accounts {
		if a.UserID == "anonymous" && a.Enabled != nil {
			return strconv.FormatBool(*a.Enabled)
		}
	}
	return "unset"
}
package main

import (
	"context"
	"errors"
	"fmt"
	"reflect"

	"github.com/anthnel/devdesk/internal/nexusbench"
)

// render prints the manifests. It builds no dependency: it contacts nothing.
func (s *session) render() int {
	out, err := nexusbench.Render(s.p)
	if err != nil {
		return s.fail(err)
	}
	if _, err := s.stdout.Write(out); err != nil {
		return s.fail(err)
	}
	return exitOK
}

// open resolves the secrets path and builds the runner and the store, in that
// order, before anything touches the cluster. Both are refused here when they
// cannot work: kubectl missing, a secrets path that git does not ignore.
func (s *session) open() (nexusbench.Runner, nexusbench.SecretStore, error) {
	if s.p.SecretsPath == "" {
		path, err := nexusbench.DefaultSecretsPath(s.p.Context, s.p.Namespace, s.getenv)
		if err != nil {
			return nil, nil, err
		}
		s.p.SecretsPath = path
	}
	runner, err := s.d.newRunner(s.p.Context)
	if err != nil {
		return nil, nil, err
	}
	store, err := s.d.newStore(s.p.SecretsPath)
	if err != nil {
		return nil, nil, err
	}
	return runner, store, nil
}

// doors are the two doors the seed goes through besides kubectl: the
// port-forward to the upstream and the image copier.
type doors struct {
	forwarder nexusbench.PortForwarder
	copier    nexusbench.ImageCopier
}

// openDoors builds the doors of the seed, the forwarder first. They are built
// before anything touches the cluster: a host without skopeo is refused here,
// not after the deployment.
func (s *session) openDoors() (doors, error) {
	forwarder, err := s.d.newForwarder(s.p.Context)
	if err != nil {
		return doors{}, err
	}
		provision:  nexusbench.Provision,
		destroy:    nexusbench.Destroy,

		newForwarder:   nexusbench.NewExecPortForwarder,
		newCopier:      nexusbench.NewSkopeoCopier,
		ensureUpstream: nexusbench.EnsureUpstream,
		seed:           nexusbench.Seed,
		readUpstream:   nexusbench.ReadUpstream,
		readImages:     readImagesAnonymously,
	}
}

func main() {
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	// After the first signal cancels ctx, hand the signals back to the default
	// behavior so that a second Ctrl-C kills a run that is slow to wind down.
	context.AfterFunc(ctx, stop)
	code := run(ctx, os.Args[1:], os.Getenv, os.Stdout, os.Stderr, defaultDeps())
	stop()
	os.Exit(code)
}

// session is one subcommand being run: its context, its resolved parameters and
// its streams.
type session struct {
	ctx    context.Context
	p      nexusbench.Params
	getenv func(string) string
	stdout io.Writer
	stderr io.Writer
	d      deps
	// restHost is where the REST API is reached; explicit tells whether the
	// operator chose it.
	restHost string
	explicit bool
}

// run executes one command line and returns the exit code: 0 for success, 1
// for a failure of the bench, 2 for a mistake in the command line.
func run(ctx context.Context, args []string, getenv func(string) string, stdout, stderr io.Writer, d deps) int {
	if len(args) == 0 {
		printUsage(stderr)
		return exitUsage
	}
	name := args[0]
	switch name {
	case "-h", "--help", "help":
		printUsage(stdout)
		return exitOK
	case "up", "provision", "down", "seed", "status", "render":
	default:
		_, _ = fmt.Fprintf(stderr, "nexus-bench: unknown subcommand %q\n\n", name)
		printUsage(stderr)
		return exitUsage
	}

	flags := newFlagSet(name)
	if err := flags.parse(args[1:]); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			printSubcommandHelp(stdout, name, flags)
			return exitOK
		}
		_, _ = fmt.Fprintf(stderr, "nexus-bench %s: %v\nRun nexus-bench %s -h for the flags.\n", name, err, name)
		return exitUsage
	}

	s := &session{ctx: ctx, getenv: getenv, stdout: stdout, stderr: stderr, d: d, restHost: loopbackHost}
	p, err := flags.resolveParams(getenv)
	if err != nil {
		return s.fail(err)
	}
	s.p = p
	if host, given := flags.restHostGiven(); given {
		if err := validateRESTHost(host); err != nil {
			return s.fail(err)
		}
		s.restHost, s.explicit = host, true
	}

	switch name {
	case "up":
		return s.up()
	case "provision":
		return s.provision()
	case "down":
		return s.down()
	case "seed":
		return s.seed()
	case "status":
		return s.status()
	default:
		return s.render()
	}
}

// fail prints err on stderr and returns the failure code. A BenchError (also
// when wrapped or joined) is printed as its own message and nothing else: the
// text around it and the error it wraps can carry what a sub-process printed,
// a credential included. A cancelled run says so.
func (s *session) fail(err error) int {
	var be *nexusbench.BenchError
	switch {
	case errors.As(err, &be):
		_, _ = fmt.Fprintln(s.stderr, be.Error())
	case errors.Is(err, context.Canceled):
		_, _ = fmt.Fprintln(s.stderr, "cancelled; the cluster keeps what was already done, run nexus-bench status to see it")
	default:
		_, _ = fmt.Fprintln(s.stderr, err.Error())
	}
	return exitFailure
}

// warn prints a warning on stderr.
func (s *session) warn(format string, args ...any) {
	_, _ = fmt.Fprintf(s.stderr, "warning: "+format+"\n", args...)
}

// restURL is the REST origin the credentials are sent to.
func (s *session) restURL() string {
	return nexusbench.RESTBaseURL(s.restHost, s.p)
}

// warnIfClearText says so when the admin credentials leave this machine.
func (s *session) warnIfClearText() {
	if s.explicit && !isLoopbackHost(s.restHost) {
		s.warn("%s is plain HTTP: the credentials travel in clear text to %s", s.restURL(), s.restHost)
	}
}

package nexusbench

import (
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"time"
)

const (
	// upstreamServiceName and upstreamServicePort are the Service of the bench
	// upstream registry and the port the port-forward reaches.
	upstreamServiceName = upstreamDeployment
	upstreamServicePort = 5000

	// seedListWait bounds the wait for a repository to list what the seed put in
	// it (H-COMPONENTS), and seedListInterval separates two readings.
	seedListWait     = 30 * time.Second
	seedListInterval = 2 * time.Second

	// seedLoopbackHost is the only host the port-forward may be reached on.
	seedLoopbackHost = "127.0.0.1"

	// resetCheck is what a repository that holds more than the data set asks.
	resetCheck = "run `mise run nexus-bench:reset` to bring the bench back to its initial state"
)

// SeedDeps are the doors Seed goes through: the cluster (to read the upstream),
// the port-forward to the upstream, the image copier, the clock of the bounded
// wait and the stored secrets.
type SeedDeps struct {
	Runner    Runner
	Forwarder PortForwarder
	Copier    ImageCopier
	Clock     Clock
	Store     SecretStore
}

// SeedResult is what Seed leaves in place: the data set, every digest filled,
// PullThrough true exactly for the images now cached in docker-proxy.
type SeedResult struct{ Images []DatasetImage }

// Seed puts the data set (D-I) in place, in this order: the stored credentials,
// the state of the upstream (read only), the OCI layout in a temporary folder,
// the port-forward to the upstream and the upstream images, the end of the
// port-forward, the docker-hosted images, the pull-through of the PullThrough
// images by docker-proxy, and the two listings, which must hold the data set and
// nothing else. An image is copied only when the digest read at its destination
// differs from the one of the data set, so a second run copies nothing.
//
// Seed never scales, applies or writes to Nexus, and it never restores a cut
// upstream (NX-02b): a cut, missing or starting upstream is a SeedFailed before
// the first copy. Docker-proxy is read only for the PullThrough images (F9): a
// read of mirror/uncached through it would cache it, and only reset removes
// that. Every failure is a *BenchError whose cause stays reachable with
// errors.Is and is never printed, but a cancelled context, which is returned
// as is. A nil out discards the progress lines ("seed: ...", no password).
func Seed(ctx context.Context, d SeedDeps, baseURL string, p Params, out io.Writer) (SeedResult, error) {
	if out == nil {
		out = io.Discard
	}
	if err := ctx.Err(); err != nil {
		return SeedResult{}, err
	}
	admin, pull, c, err := seedCredentials(ctx, d.Store, baseURL)
	if err != nil {
		return SeedResult{}, err
	}
	defer c.closeIdle()
	if err := requireSeedableUpstream(ctx, d.Runner, p); err != nil {
		return SeedResult{}, err
	}

	images := Dataset()
	s := &seeder{ctx: ctx, d: d, p: p, out: out, c: c, baseURL: baseURL, admin: admin, pull: pull, images: images}
	root, err := os.MkdirTemp("", "nexus-bench-seed-")
	if err != nil {
		return SeedResult{}, &BenchError{
			Kind:  SeedFailed,
			Cause: "the temporary folder of the seed cannot be created",
			Check: "check that TMPDIR is a folder this user can write to",
			Err:   err,
		}
	}
	defer func() { _ = os.RemoveAll(root) }()
	if err := s.writeLayout(root); err != nil {
		return SeedResult{}, err
	}
	steps := []func() error{
		s.seedUpstream,
		s.seedHosted,
		func() error { return s.pullThrough(root) },
		func() error { return s.verify(dockerProxyRepository, s.wanted(isPullThrough)) },
		func() error { return s.verify(dockerHostedRepository, s.wanted(isHosted)) },
	}
	for _, step := range steps {
		if err := step(); err != nil {
			return SeedResult{}, err
		}
	}
	s.say("the data set is in place: %d images", len(images))
	return SeedResult{Images: images}, nil
}

// nexusImageRef is the one place that builds the reference of an image of a
// repository of the bench Nexus ("docker-hosted" or "docker-proxy"). Today it is
// the path routing on the HTTP NodePort (H-PATH): 127.0.0.1:<HTTPNodePort>/
// <repository>/<name>:<tag>. Step 12 settles whether the instance serves it.
func nexusImageRef(p Params, repository string, img DatasetImage) ImageRef {
	return ImageRef{
		Transport: "docker",
		Location:  seedLoopbackHost + ":" + strconv.Itoa(p.HTTPNodePort) + "/" + repository + "/" + img.Name + ":" + img.Tag,
	}
}

// upstreamImageRef is the reference of an image in the bench upstream reached
// through the port-forward at local ("127.0.0.1:<port>"): <local>/<name>:<tag>.
func upstreamImageRef(local string, img DatasetImage) ImageRef {
	return ImageRef{Transport: "docker", Location: local + "/" + img.Name + ":" + img.Tag}
}

// seedCredentials reads the two accounts of the bench from the store and
// returns the admin client of the final listings. Nothing is sent to Nexus.
func seedCredentials(ctx context.Context, store SecretStore, baseURL string) (admin, pull Credentials, c *client, err error) {
	c, sec, err := adminFromStore(ctx, baseURL, store)
	if err != nil {
		if cerr := ctx.Err(); cerr != nil {
			return admin, pull, nil, cerr
		}
		return admin, pull, nil, err
	}
	if sec.PullPassword == "" {
		return admin, pull, nil, &BenchError{
			Kind:  ProvisionFailed,
			Cause: "the bench has no " + pullUserID + " password stored: its provisioning did not finish",
			Check: upCheck,
			Err:   errors.New("no pull password in the secrets file"),
		}
	}
	return Credentials{User: adminUserID, Password: REDACTED, Credentials{User: pullUserID, Password: REDACTED, c, nil
}

// requireSeedableUpstream refuses what the seed cannot fill: an upstream URL the
// bench did not deploy (the proxy would not read what the seed pushes), and an
// upstream that is missing, cut or still starting. It writes nothing: bringing a
// cut upstream back is NX-02b.
func requireSeedableUpstream(ctx context.Context, r Runner, p Params) error {
	if !p.UpstreamIsBench() {
		return &BenchError{
			Kind:  SeedFailed,
			Cause: fmt.Sprintf("%s points at an upstream the bench did not deploy, and the seed pushes to the upstream of the bench only", envUpstreamURL),
			Check: "unset " + envUpstreamURL + " to use the bench upstream",
		}
	}
	state, err := ReadUpstream(ctx, r, p)
	if err != nil {
		return err
	}
	switch state {
	case UpstreamMissing:
		return &BenchError{
			Kind:  SeedFailed,
			Cause: fmt.Sprintf("the upstream %s does not exist in namespace %q", upstreamDeployment, p.Namespace),
			Check: "run `mise run nexus-bench:up`, which deploys it",
		}
	case UpstreamCut:
		return &BenchError{
			Kind:  SeedFailed,
			Cause: "the upstream is cut",
			Check: "run `mise run nexus-bench:restore-upstream`, then the seed again",
		}
	case UpstreamStarting:
		return &BenchError{
			Kind:  SeedFailed,
			Cause: "the upstream is still starting",
			Check: "wait for its pod to be Ready (" + podsCommand(p) + "), then run the seed again",
		}
	}
	return nil
}

// seeder is one run of Seed.
type seeder struct {
	ctx     context.Context
	d       SeedDeps
	p       Params
	out     io.Writer
	c       *client
	baseURL string
	admin   Credentials
	pull    Credentials
	images  []DatasetImage // Dataset(), digests filled
	layout  string         // the OCI layout folder
	refs    []string       // the layout reference of images[i]
}

func (s *seeder) say(format string, args ...any) {
	_, _ = fmt.Fprintf(s.out, "seed: "+format+"\n", args...)
}

// writeLayout writes the data set as an OCI layout under root.
func (s *seeder) writeLayout(root string) error {
	s.layout = filepath.Join(root, "layout")
	err := os.Mkdir(s.layout, 0o700)
	if err == nil {
		s.refs, err = WriteLayout(s.layout, s.images)
	}
	if err != nil {
		return &BenchError{
			Kind:  SeedFailed,
			Cause: "the OCI layout of the data set cannot be written",
			Check: "check that TMPDIR has room and is writable",
			Err:   err,
		}
	}
	return nil
}

// source is the layout reference of images[i].
func (s *seeder) source(i int) ImageRef {
	return ImageRef{Transport: "oci", Location: s.layout + ":" + s.refs[i]}
}

func isPullThrough(img DatasetImage) bool { return img.PullThrough }

func isHosted(img DatasetImage) bool { return img.Location == LocationHosted }

// wanted lists the images of the data set that keep.
func (s *seeder) wanted(keep func(DatasetImage) bool) []DatasetImage {
	var out []DatasetImage
	for _, img := range s.images {
		if keep(img) {
			out = append(out, img)
		}
	}
	return out
}

// seedUpstream pushes the upstream images through a port-forward that is always
// stopped before it returns.
func (s *seeder) seedUpstream() error {
	local, stop, err := s.d.Forwarder.Forward(s.ctx, s.p.Namespace, upstreamServiceName, upstreamServicePort)
	if err != nil {
		return s.failure(err, "the port-forward to the upstream")
	}
	if stop != nil {
		defer func() { _ = stop() }()
	}
	if !strings.HasPrefix(local, seedLoopbackHost+":") || !loopbackRegistry(local) {
		return &BenchError{
			Kind:  SeedFailed,
			Cause: "the port-forward to the upstream is not on 127.0.0.1",
			Check: "the bench pushes to a registry on the loopback only: check the kubectl on PATH",
		}
	}
	for i, img := range s.images {
		if img.Location != LocationUpstream {
			continue
		}
		if err := s.push(i, upstreamImageRef(local, img), nil, "the upstream"); err != nil {
			return err
		}
	}
	return nil
}

// seedHosted pushes the docker-hosted images with the admin account.
func (s *seeder) seedHosted() error {
	for i, img := range s.images {
		if img.Location != LocationHosted {
			continue
		}
		if err := s.push(i, nexusImageRef(s.p, dockerHostedRepository, img), &s.admin, dockerHostedRepository); err != nil {
			return err
		}
	}
	return nil
}

// push copies images[i] from the layout to dst unless dst already holds the
// digest of the data set. A proven absence (errImageAbsent) is a copy; any
// other failure to read stops the seed.
func (s *seeder) push(i int, dst ImageRef, creds *Credentials, where string) error {
	img := s.images[i]
	name := img.Name + ":" + img.Tag
	have, err := s.d.Copier.ManifestDigest(s.ctx, dst, creds)
	if errors.Is(err, errImageAbsent) {
		have, err = "", nil
	}
	if err != nil {
		return s.failure(err, "reading "+name+" in "+where)
	}
	if have == img.Digest {
		s.say("%s is already in %s", name, where)
		return nil
	}
	s.say("copying %s to %s", name, where)
	err = s.d.Copier.Copy(s.ctx, s.source(i), dst, CopyOptions{DestCreds: creds, PreserveDigests: true})
	if err != nil {
		return s.failure(err, "copying "+name+" to "+where)
	}
	return nil
}

// pullThrough has docker-proxy pull each PullThrough image from the upstream
// with the bench-pull account, into a folder that is thrown away. Only these
// images are ever read through the proxy (F9): it caches whatever it serves. An
// image the proxy already lists with the right digest is not pulled again.
func (s *seeder) pullThrough(root string) error {
	cached, err := s.c.listComponents(s.ctx, dockerProxyRepository)
	if err != nil {
		return s.restFailure(err)
	}
	for i, img := range s.images {
		if !img.PullThrough {
			continue
		}
		name := img.Name + ":" + img.Tag
		if listed(cached, img) {
			s.say("%s is already cached by %s", name, dockerProxyRepository)
			continue
		}
		s.say("pulling %s through %s", name, dockerProxyRepository)
		dst := ImageRef{Transport: "dir", Location: filepath.Join(root, fmt.Sprintf("pull-%02d", i+1))}
		src := nexusImageRef(s.p, dockerProxyRepository, img)
		if err := s.d.Copier.Copy(s.ctx, src, dst, CopyOptions{SrcCreds: &s.pull, PreserveDigests: true}); err != nil {
			return s.failure(err, "pulling "+name+" through "+dockerProxyRepository)
		}
	}
	return nil
}

// listed reports whether components hold img: its name and tag are enough, a
// component the instance lists without a digest counts as present (H-COMPONENTS),
// and a digest it does list must be the one of the data set.
func listed(components []component, img DatasetImage) bool {
	for _, comp := range components {
		if comp.Name == img.Name && comp.Version == img.Tag {
			return comp.Digest == "" || comp.Digest == img.Digest
		}
	}
	return false
}

// verify waits, for at most seedListWait, until repo lists every image of want
// and nothing else (H-COMPONENTS). A component outside the data set cannot be
// waited away: it fails at once and asks for a reset.
func (s *seeder) verify(repo string, want []DatasetImage) error {
	deadline := s.d.Clock.Now().Add(seedListWait)
	for {
		comps, err := s.c.listComponents(s.ctx, repo)
		if err != nil {
			return s.restFailure(err)
		}
		if extra := outside(comps, want); len(extra) > 0 {
			return &BenchError{
				Kind:  SeedFailed,
				Cause: fmt.Sprintf("%s holds images outside the dataset (%s)", repo, strings.Join(extra, ", ")),
				Check: resetCheck,
			}
		}
		missing := absent(comps, want)
		if len(missing) == 0 {
			s.say("%s lists the %d images of the data set", repo, len(want))
			return nil
		}
		if !s.d.Clock.Now().Before(deadline) {
			return &BenchError{
				Kind:  SeedFailed,
				Cause: fmt.Sprintf("%s does not list %s after %s", repo, strings.Join(missing, ", "), seedListWait),
				Check: "run the seed again, and read the log of the pod if it persists: " + podsCommand(s.p),
			}
		}
		if err := s.d.Clock.Sleep(s.ctx, seedListInterval); err != nil {
			return err
		}
	}
}

// outside lists the "name:tag" of the components that are not in want.
func outside(components []component, want []DatasetImage) []string {
	var out []string
	for _, comp := range components {
		known := false
		for _, img := range want {
			known = known || (comp.Name == img.Name && comp.Version == img.Tag)
		}
		if !known {
			out = append(out, comp.Name+":"+comp.Version)
		}
	}
	return out
}

// absent lists the "name:tag" of the images of want that components do not list
// with the right digest.
func absent(components []component, want []DatasetImage) []string {
	var out []string
	for _, img := range want {
		if !listed(components, img) {
			out = append(out, img.Name+":"+img.Tag)
		}
	}
	return out
}

// failure is the error of a step of a door (copier, forwarder): a cancelled
// context is returned as is, a *BenchError keeps its kind and gains the step,
// and anything else becomes a *BenchError that keeps the cause for errors.Is
// without printing it (the text of a sub-process can carry a credential).
func (s *seeder) failure(err error, step string) error {
	if cerr := s.ctx.Err(); cerr != nil {
		return cerr
	}
	var be *BenchError
	if errors.As(err, &be) {
		return &BenchError{Kind: be.Kind, Cause: step + ": " + be.Cause, Check: be.Check, Err: err}
	}
	return &BenchError{
		Kind:  Unclassified,
		Cause: step + " failed",
		Check: "run the same command by hand to see what it says",
		Err:   err,
	}
}

// restFailure is the error of a listing of Nexus.
func (s *seeder) restFailure(err error) error {
	if cerr := s.ctx.Err(); cerr != nil {
		return cerr
	}
	return asBenchError(err, s.p, s.baseURL)
}
package nexusbench

import (
	"context"
	"errors"
	"net/http"
	"net/url"
	"strings"
)

const (
	// componentsPath lists the components of a repository.
	componentsPath = restAPI + "/components"
	// maxComponentPages bounds a listing: a continuation token that never ends
	// is an error after this many calls, not an endless loop.
	maxComponentPages = 1000
	// manifestMarker is what the path of a Docker manifest asset holds:
	// v2/<name>/manifests/<tag>.
	manifestMarker = "/manifests/"

	// upCheck is what a missing admin password asks the operator to do.
	upCheck = "run `mise run nexus-bench:up` to provision the bench"
)

// component is one image tag a repository lists: the image name, the tag and,
// when the instance lists it, the digest of the manifest ("sha256:<hex>").
type component struct {
	Name    string
	Version string
	Digest  string
}

// ListedImage is one image tag a repository lists: the name, the tag and the
// manifest digest ("sha256:<hex>", empty when the instance lists none).
type ListedImage struct{ Name, Tag, Digest string }

// ListImagesAnonymously lists the images of repo on the instance at baseURL
// with no credential at all: it is a read of what anonymous access allows, and
// a 401 or 403 is an *APIError like any other refusal. It is the listing of the
// status command, which never reads docker-group (F9) and never starts skopeo.
func ListImagesAnonymously(ctx context.Context, baseURL, repo string) ([]ListedImage, error) {
	c := newClient(baseURL, "", "")
	defer c.closeIdle()
	list, err := c.listComponents(ctx, repo)
	if err != nil {
		return nil, err
	}
	out := make([]ListedImage, 0, len(list))
	for _, comp := range list {
		out = append(out, ListedImage{Name: comp.Name, Tag: comp.Version, Digest: comp.Digest})
	}
	return out, nil
}

// adminFromStore returns a client authenticated with the stored admin password
// and the stored secrets. It never reads the initial password of the pod: seed,
// restore and reset need a bench that up already provisioned. It sends no
// request, so a stored password the instance refuses shows on the first call.
func adminFromStore(ctx context.Context, baseURL string, store SecretStore) (*client, Secrets, error) {
	if err := ctx.Err(); err != nil {
		return nil, Secrets{}, &transportError{Op: "read the stored admin password", Err: err}
	}
	sec, found, err := store.Load()
	if err != nil {
		return nil, Secrets{}, &BenchError{
			Kind:  ProvisionFailed,
			Cause: "the secrets file of the bench cannot be read",
			Check: "check the permissions and the content of the secrets file, then " + upCheck,
			Err:   err,
		}
	}
	if !found || sec.AdminPassword == "" {
		return nil, Secrets{}, &BenchError{
			Kind:  ProvisionFailed,
			Cause: "the bench has no admin password stored: it was never provisioned, or its provisioning did not finish",
			Check: upCheck,
			Err:   errors.New("no admin password in the secrets file"),
		}
	}
	return newClient(baseURL, adminUserID, sec.AdminPassword), sec, nil
}

// componentPage is one page of GET /v1/components.
type componentPage struct {
	Items             []componentItem `json:"items"`
	ContinuationToken *string         `json:"continuationToken"`
}

type componentItem struct {
	Name    string           `json:"name"`
	Version string           `json:"version"`
	Assets  []componentAsset `json:"assets"`
}

type componentAsset struct {
	Path     string `json:"path"`
	Checksum struct {
		SHA256 string `json:"sha256"`
	} `json:"checksum"`
}

// listComponents lists the components of repo, following the continuation token
// until the last page; a token equal to the previous one is an error. A
// repository the instance does not know lists as no component. An error on any
// page drops what the earlier pages returned.
//
// H-COMPONENTS (to settle at step 12): a Docker component is one image tag, and
// the sha256 checksum of its asset under v2/<name>/manifests/<tag> is the digest
// of the manifest.
func (c *client) listComponents(ctx context.Context, repo string) ([]component, error) {
	op := "list the components of " + repo
	var out []component
	token := ""
	for page := 0; page < maxComponentPages; page++ {
		query := url.Values{"repository": {repo}}
		if token != "" {
			query.Set("continuationToken", token)
		}
		var body componentPage
		found, err := c.get(ctx, op, componentsPath, query, &body)
		if err != nil {
			return nil, err
		}
		if !found {
			if page == 0 {
				return nil, nil
			}
			return nil, &APIError{Op: op, Status: http.StatusNotFound}
		}
		for _, item := range body.Items {
			out = append(out, component{Name: item.Name, Version: item.Version, Digest: manifestDigest(item)})
		}
		if body.ContinuationToken == nil || *body.ContinuationToken == "" {
			return out, nil
		}
		// The same token as the previous page would repeat that page for ever.
		if *body.ContinuationToken == token {
			return nil, &decodeError{Op: op, Err: errors.New("the continuation token repeats")}
		}
		token = *body.ContinuationToken
	}
	return nil, &decodeError{Op: op, Err: errors.New("the continuation token never ends")}
}

// manifestDigest returns "sha256:<hex>" of the manifest asset of item, or "" when
// the instance lists none. The asset of the tag itself wins over any other
// manifest asset (a digest-addressed one, for instance).
func manifestDigest(item componentItem) string {
	digest := ""
	for _, a := range item.Assets {
		if a.Checksum.SHA256 == "" || !strings.Contains(a.Path, manifestMarker) {
			continue
		}
		if strings.HasSuffix(a.Path, manifestMarker+item.Version) {
			return "sha256:" + a.Checksum.SHA256
		}
		if digest == "" {
			digest = "sha256:" + a.Checksum.SHA256
		}
	}
	return digest
}

