+		pf.waitErr = cmd.Wait()
+		close(pf.done)
+	}()
+
+	timer := time.NewTimer(portForwardTimeout)
+	defer timer.Stop()
+	select {
+	case local := <-lines.found:
+		return local, pf.stop, nil
+	case <-pf.done:
