//   - `status` reads the data set against the descriptor, with the digests of
//     the REST listing of docker-hosted and docker-proxy, anonymously.

import (
	"bytes"
	"context"
	"errors"
	"os"
	"path/filepath"
	"reflect"
	"slices"
	"strconv"
	"strings"
	"testing"
